fn token_flight(
    active: Beat,
    time: f32,
    tokens: Vec<OutputToken>,
    columns: usize,
    sources: TokenBounds,
    destinations: TokenBounds,
) -> impl IntoElement {
    canvas(
        |_, _, _| (),
        move |_, _, w, cx| {
            let sources = sources.borrow();
            let destinations = destinations.borrow();
            for (slot, token) in tokens.iter().enumerate() {
                let t = (time - token.start) / FLIGHT;
                if !(0. ..1.).contains(&t) {
                    continue;
                }
                let source_index = if token.draft { slot } else { columns + slot };
                let Some(source) = sources.get(source_index) else {
                    continue;
                };
                let Some(dest) = destinations.get(active.first_token + slot) else {
                    continue;
                };
                if source.size.height <= px(0.) || dest.size.width <= px(0.) {
                    continue;
                }
                let start = if token.draft {
                    source.origin + point(px(10.), px(6.))
                } else {
                    source.origin
                };
                let mut run = w.text_style().to_run(token.text.trim_start().len());
                run.color = Paint::get(cx)
                    .ink
                    .opacity((1. - ((t - 0.82) / 0.18).clamp(0., 1.)).min(t * 8.));
                let line = w.text_system().shape_line(
                    token.text.trim_start().to_string().into(),
                    px(14.),
                    &[run],
                    None,
                );
                let progress = ((1. - (1. + 8. * t) * (-8. * t).exp()) / 0.99698).clamp(0., 1.);
                let finish = dest.origin
                    + point(
                        px(if token.text.starts_with(' ') { 3. } else { 0. }),
                        px(2.5),
                    );
                let _ = line.paint(
                    start + (finish - start) * progress,
                    px(20.),
                    TextAlign::Left,
                    None,
                    w,
                    cx,
                );
            }
        },
    )
    .absolute()
    .inset_0()
}

impl SpeculativeDecoding {
    fn tick(&mut self, w: &Window, cx: &mut Context<Self>) {
        let bounds = self.bounds.get();
        let viewport = w.viewport_size();
        let visible_height = bounds.bottom().min(viewport.height) - bounds.top().max(px(0.));
        let in_view = visible_height > bounds.size.height * 0.15;
        let ready = self.visible
            && w.is_visible()
            && in_view
            && self.status == DecodeStatus::Ready
            && !self.rounds.is_empty();
        if ready
            && self.autoplay
            && !self.started
            && !disabled_motion(cx)
            && visible_height > bounds.size.height * 0.60
        {
            self.started = true;
            self.playing = true;
            self.clear_clock(cx);
        }
        if !ready || !self.playing {
            self.clear_clock(cx);
            return;
        }
        let age = self.clock.age(cx);
        if !age.is_finite() {
            self.clear_clock(cx);
            return;
        }
        self.elapsed = (self.elapsed + (age - self.last_age).clamp(0., 0.05)).min(self.end());
        self.last_age = age;
        if !self.completed && self.elapsed >= self.plan.end() {
            self.completed = true;
            let stats = self.plan.totals.last().cloned().unwrap_or_default();
            self.announcement = if crate::primitives::control::UiLanguage::current(cx)
                == crate::primitives::control::UiLanguage::Chinese
            {
                format!("完成 · {} 次验证", stats.passes).into()
            } else {
                format!("Done in {} target passes", stats.passes).into()
            };
            cx.emit(DecodeCompleted(stats));
        }
        if self.elapsed < self.end() {
            w.request_animation_frame();
        } else {
            self.playing = false;
        }
    }

    fn slider(&mut self, ready: bool, p: Paint, cx: &mut Context<Self>) -> Div {
        let focus = self
            .slider_focus
            .get_or_insert_with(|| cx.focus_handle().tab_stop(true))
            .clone();
        let name = tr(cx, "Draft length", "草稿长度");
        let value = format!("{} {}", self.draft_length, tr(cx, "tokens", "个 token"));
        let fraction = (self.draft_length - 2) as f32 / 6.;
        let track = self.track.clone();
        let drag =
            cx.listener(|s, event: &MouseMoveEvent, _, cx| s.move_slider(event.position, cx));
        let end = cx.listener(|s, _: &MouseUpEvent, _, _| s.dragging = false);
        let touch = self.touch.listen(cx, |s, event, w, cx| match event.phase {
            TouchPhase::Started if s.status == DecodeStatus::Ready => {
                s.dragging = true;
                if let Some(focus) = &s.slider_focus {
                    focus.focus(w, cx);
                }
                s.move_slider(event.position, cx);
            }
            TouchPhase::Moved => s.move_slider(event.position, cx),
            TouchPhase::Ended | TouchPhase::Cancelled => s.dragging = false,
            _ => {}
        });
        let thumb = div()
            .id("decode-length-thumb")
            .role(Role::Slider)
            .aria_label(name)
            .aria_value(value.clone())
            .aria_numeric_value(self.draft_length as f64)
            .aria_min_numeric_value(2.)
            .aria_max_numeric_value(8.)
            .aria_numeric_value_step(1.)
            .track_focus(&focus)
            .tab_stop(ready)
            .absolute()
            .left(relative(fraction))
            .ml(px(-11.))
            .top(px(9.))
            .size(px(22.))
            .rounded_full()
            .bg(p.panel)
            .border_1()
            .border_color(p.line)
            .shadow_sm()
            .focus_visible(move |d| d.border_2().border_color(p.focus))
            .on_key_down(cx.listener(|s, e: &KeyDownEvent, w, cx| {
                let value = match e.keystroke.key.as_str() {
                    "left" | "down" => s.draft_length.saturating_sub(1),
                    "right" | "up" => s.draft_length + 1,
                    "home" => 2,
                    "end" => 8,
                    _ => return,
                };
                s.change_length(value, cx);
                w.prevent_default();
                cx.stop_propagation();
            }));
        let measured = canvas(
            move |bounds, _, _| track.set(bounds),
            move |_, _, w, _| {
                if ready {
                    w.on_mouse_event(move |e: &MouseMoveEvent, phase, w, cx| {
                        if phase.capture() {
                            drag(e, w, cx);
                        }
                    });
                    w.on_mouse_event(move |e: &MouseUpEvent, phase, w, cx| {
                        if phase.capture() && e.button == MouseButton::Left {
                            end(e, w, cx);
                        }
                    });
                }
            },
        )
        .absolute()
        .inset_0();
        let rail = div()
            .relative()
            .mx(px(11.))
            .h(px(40.))
            .child(measured)
            .child(
                div()
                    .absolute()
                    .left_0()
                    .right_0()
                    .top(px(17.))
                    .h(px(6.))
                    .rounded_full()
                    .bg(p.hover),
            )
            .child(
                div()
                    .absolute()
                    .left_0()
                    .w(relative(fraction))
                    .top(px(17.))
                    .h(px(6.))
                    .rounded_full()
                    .bg(p.bright),
            )
            .child(thumb);
        let slot = div()
            .id("decode-length")
            .relative()
            .cursor_pointer()
            .child(rail)
            .when(ready, |d| {
                d.child(touch).on_mouse_down(
                    MouseButton::Left,
                    cx.listener(|s, e: &MouseDownEvent, w, cx| {
                        if w.last_input_was_touch() {
                            return;
                        }
                        s.dragging = true;
                        if let Some(focus) = &s.slider_focus {
                            focus.focus(w, cx);
                        }
                        s.move_slider(e.position, cx);
                    }),
                )
            });
        column()
            .min_w_0()
            .w_full()
            .max_w(px(320.))
            .gap(px(4.))
            .child(
                row()
                    .justify_between()
                    .gap(px(4.))
                    .child(text(name, 14., 20., p.ink))
                    .child(text(value, 14., 20., p.secondary)),
            )
            .child(slot)
    }

    fn stats_row(
        &mut self,
        stats: DecodeStats,
        narrow: bool,
        p: Paint,
        cx: &mut Context<Self>,
    ) -> Div {
        let font_size = if narrow { 20. } else { 22. };
        let values = [
            stats.speedup as f64,
            (stats.acceptance * 100.).round() as f64,
            stats.tokens_per_pass as f64,
        ];
        let counters = self.counters.get_or_insert_with(|| {
            [0, 1, 2].map(|i| {
                cx.new(|_| {
                    AnimatedCounter::new(0.)
                        .with_size(font_size)
                        .with_accessibility(false)
                        .with_decimals(usize::from(i != 1))
                        .with_suffix(["×", "%", ""][i])
                })
            })
        });
        let labels = [
            tr(cx, "Faster", "加速比"),
            tr(cx, "Drafts accepted", "草稿接受率"),
            tr(cx, "Tokens per pass", "每次验证词元"),
        ];
        row()
            .w_full()
            .items_start()
            .gap(px(if narrow { 12. } else { 16. }))
            .children(labels.into_iter().zip(counters.iter()).enumerate().map(
                |(i, (label, counter))| {
                    let value = values[i];
                    counter.update(cx, |c, cx| {
                        c.set_wheel_size(font_size);
                        c.set_visible(self.visible, cx);
                        c.set_value(value, cx);
                    });
                    let available = if i == 1 {
                        stats.drafted > 0
                    } else {
                        stats.passes > 0
                    };
                    let spoken = if available {
                        format!("{label} {:.1}{}", value, ["×", "%", ""][i])
                    } else {
                        format!("{label} · {}", tr(cx, "not yet", "尚无数据"))
                    };
                    column()
                        .id(("decode-stat", i))
                        .role(Role::Label)
                        .aria_label(spoken)
                        .min_w_0()
                        .flex_1()
                        .gap(px(2.))
                        .child(
                            div()
                                .h(px(font_size + 5.))
                                .flex()
                                .items_center()
                                .when(available, |d| d.child(counter.clone()))
                                .when(!available, |d| {
                                    d.child(text("–", font_size, font_size + 5., p.secondary))
                                }),
                        )
                        .child(text(label, 12., 17., p.secondary))
                },
            ))
    }
}

impl Render for SpeculativeDecoding {
    fn render(&mut self, w: &mut Window, cx: &mut Context<Self>) -> impl IntoElement {
        self.tick(w, cx);
        let colors = ModelPaint::new(cx);
        let p = colors.theme;
        let radius = surface_radius(cx);
        let reduced = disabled_motion(cx);
        let bounds = self.bounds.get();
        let width = if bounds.size.width > px(0.) {
            f32::from(bounds.size.width)
        } else {
            (f32::from(w.viewport_size().width) - 32.).clamp(200., 720.)
        };
        let narrow = width < NARROW;
        let stacked_lanes = width < 640.;
        let pad = if narrow { 16. } else { 24. };
        let inner_width = width - pad * 2. - 2.;
        let line_width = (inner_width - if stacked_lanes { 0. } else { 136. }).max(50.);
        let ready = self.status == DecodeStatus::Ready;
        let time = self.elapsed;
        let done = self.plan.passed(time);
        let finished = self.completed;
        let active = self.plan.beats.get(done).copied();
        let round = self.rounds.get(done);
        let totals = self.plan.totals[done].clone();
        let baseline = (time / self.pass).floor() as usize;
        let baseline = baseline.min(self.plan.tokens.len());
        let status = match self.status {
            DecodeStatus::Loading => tr(cx, "Loading run…", "正在加载运行记录…").to_owned(),
            DecodeStatus::Failed if self.error.is_empty() => {
                tr(cx, "Unable to load the run", "无法加载运行记录").to_owned()
            }
            DecodeStatus::Failed => self.error.to_string(),
            DecodeStatus::Ready if self.rounds.is_empty() => {
                tr(cx, "No rounds supplied", "没有可回放的轮次").to_owned()
            }
            DecodeStatus::Ready
                if finished && self.compare && baseline < self.plan.tokens.len() =>
            {
                if tr(cx, "en", "zh") == "zh" {
                    format!("推测解码已用 {done} 次验证完成，仅目标模型仍在写入")
                } else {
                    format!("Speculation done in {done} passes, target alone still writing")
                }
            }
            DecodeStatus::Ready if finished => {
                if tr(cx, "en", "zh") == "zh" {
                    format!("完成 · {done} 次目标验证")
                } else {
                    format!("Done in {done} target passes")
                }
            }
            DecodeStatus::Ready if !self.started && self.recorded => {
                tr(cx, "Recorded run", "回放记录").to_owned()
            }
            DecodeStatus::Ready if !self.started && self.tokens.is_some() => {
                if tr(cx, "en", "zh") == "zh" {
                    format!("草稿预写 {} 个 token，目标一次验证", self.draft_length)
                } else {
                    format!(
                        "Draft guesses {} tokens ahead, target checks them in one pass",
                        self.draft_length
                    )
                }
            }
            DecodeStatus::Ready if !self.playing => tr(cx, "Paused", "已暂停").to_owned(),
            DecodeStatus::Ready => {
                if let (Some(round), Some(beat)) = (round, active) {
                    let length = round.draft.len();
                    let accepted = round.accepted();
                    if tr(cx, "en", "zh") == "zh" {
                        if time < beat.drafted {
                            format!("草稿模型提出 {length} 个 token")
                        } else if time < beat.swept {
                            format!("目标模型一次验证 {length} 个 token")
                        } else {
                            format!("接受 {accepted} / {length} · 目标模型写入答案")
                        }
                    } else if time < beat.drafted {
                        format!("Draft model proposes {length} tokens")
                    } else if time < beat.swept {
                        format!("Target checks all {length} in one pass")
                    } else if accepted < length {
                        format!("{accepted} of {length} accepted, target replaces the first miss")
                    } else {
                        format!("{accepted} of {length} accepted, target adds the next token")
                    }
                } else {
                    tr(cx, "Ready to replay", "准备回放").to_owned()
                }
            }
        };
        let title = self
            .title
            .clone()
            .unwrap_or_else(|| tr(cx, "Speculative decoding", "推测解码").into());
        let status_view = self.status_label.view(
            status.into(),
            self.status == DecodeStatus::Loading && self.visible,
            if narrow { 40. } else { 20. },
            p,
            w,
            cx,
        );
        let playing = self.playing;
        let play_name = if playing {
            tr(cx, "Pause", "暂停")
        } else {
            tr(cx, "Play", "播放")
        };
        let restart_name = tr(cx, "Restart", "重新开始");
        let play_icon = if playing { Glyph::Pause } else { Glyph::Play };
        let actions = row()
            .flex_none()
            .gap(px(8.))
            .child(activate(
                face("decode-play", play_name, 32., 999., Tone::Surface, cx)
                    .w(px(32.))
                    .rounded_full()
                    .border_1()
                    .border_color(p.line)
                    .tab_stop(ready)
                    .opacity(if ready { 1. } else { 0.5 })
                    .child(icon(play_icon, 15., p.secondary)),
                cx,
                |s, _, cx| s.set_playing(!s.playing, cx),
            ))
            .child(activate(
                face("decode-restart", restart_name, 32., 999., Tone::Surface, cx)
                    .w(px(32.))
                    .rounded_full()
                    .border_1()
                    .border_color(p.line)
                    .tab_stop(ready)
                    .opacity(if ready { 1. } else { 0.5 })
                    .child(icon(Glyph::Undo, 15., p.secondary)),
                cx,
                |s, _, cx| s.restart(cx),
            ));
        let labels: [SharedString; 4] = [
            tr(cx, "Draft model", "草稿模型"),
            tr(cx, "Small, fast", "小而快"),
            tr(cx, "Target model", "目标模型"),
            tr(cx, "Large", "大型"),
        ]
        .into_iter()
        .enumerate()
        .map(|(i, label)| self.model_labels[i].clone().unwrap_or_else(|| label.into()))
        .collect::<Vec<_>>()
        .try_into()
        .unwrap_or_default();
        let lane_names = div()
            .flex()
            .flex_none()
            .gap(px(if stacked_lanes { 20. } else { 8. }))
            .when(stacked_lanes, |d| d.w_full().min_h(px(38.)).flex_wrap())
            .when(!stacked_lanes, |d| d.w(px(120.)).flex_col())
            .child(lane_label(
                labels[0].clone(),
                labels[1].clone(),
                colors.draft,
                p,
            ))
            .child(lane_label(
                labels[2].clone(),
                labels[3].clone(),
                colors.target,
                p,
            ));
        let mut widths = Vec::new();
        if self.started
            && let Some(round) = round
        {
            let accepted = round.accepted();
            let columns = round
                .draft
                .len()
                .max(accepted + usize::from(round.target.is_some()));
            for i in 0..columns {
                let draft = round
                    .draft
                    .get(i)
                    .map_or(0., |s| measure(&s.trim_start().to_string().into(), 14., w));
                let target = if i == accepted {
                    round.target.as_ref().map_or(0., |s| {
                        measure(&s.trim_start().to_string().into(), 14., w) + 19.
                    })
                } else {
                    0.
                };
                widths.push((draft.max(target) + 20.).clamp(44., line_width));
            }
        }
        let columns = widths.len();
        let sources = Rc::new(RefCell::new(vec![Bounds::default(); columns * 2]));
        let destinations = Rc::new(RefCell::new(vec![
            Bounds::default();
            self.plan.tokens.len()
        ]));
        let desired = wrap_height(widths.iter().copied(), line_width, 6., 72., 8.);
        let lanes = self.lanes.get_or_insert_with(|| Slide::new(desired));
        lanes.duration(desired, 0.4, cx);
        let lane_height = lanes.get(w, cx).max(72.);
        let default_beat = Beat {
            start: 0.,
            drafted: 0.,
            swept: 0.01,
            end: 0.01,
            first_token: 0,
            token_count: 0,
        };
        let moment = Moment {
            time,
            round: active.unwrap_or(default_beat),
            reduced,
        };
        let lane_content = div()
            .relative()
            .min_w_0()
            .flex_1()
            .w_full()
            .h(px(lane_height))
            .overflow_hidden()
            .when(columns > 0, |d| {
                d.child(draft_columns(
                    round.expect("columns require an active round"),
                    moment,
                    &widths,
                    &sources,
                    colors,
                    radius,
                ))
            })
            .when(columns == 0, |d| {
                d.child(
                    column().gap(px(8.)).children(
                        [
                            if finished {
                                if tr(cx, "en", "zh") == "zh" {
                                    format!(
                                        "草拟 {} 个，接受 {} 个",
                                        totals.drafted, totals.accepted
                                    )
                                } else {
                                    format!(
                                        "{} tokens drafted, {} accepted",
                                        totals.drafted, totals.accepted
                                    )
                                }
                            } else {
                                tr(cx, "–", "–").to_owned()
                            },
                            if finished {
                                if tr(cx, "en", "zh") == "zh" {
                                    format!(
                                        "{} 次验证写入 {} 个 token",
                                        totals.passes, totals.tokens
                                    )
                                } else {
                                    format!("{} passes for {} tokens", totals.passes, totals.tokens)
                                }
                            } else {
                                tr(cx, "–", "–").to_owned()
                            },
                        ]
                        .into_iter()
                        .map(|s| {
                            div().h(px(32.)).flex().items_center().child(text(
                                s,
                                14.,
                                20.,
                                p.secondary,
                            ))
                        }),
                    ),
                )
            });
        let landed = if reduced {
            self.plan.tokens.partition_point(|t| t.start <= time)
        } else {
            self.plan
                .tokens
                .partition_point(|t| t.start + FLIGHT <= time + 0.001)
        };
        let output_name = if self.compare {
            tr(cx, "Speculative", "推测解码")
        } else {
            tr(cx, "Output", "输出")
        };
        let written = labelled_line(
            output_name,
            done,
            narrow,
            output_line(
                &self.plan,
                landed,
                moment,
                false,
                Some(&destinations),
                colors,
                cx,
            ),
            p,
            cx,
        );
        let compare_size = wrap_height(
            self.plan.words.iter().map(|word| {
                word.clone()
                    .map(|i| measure(&self.plan.tokens[i].text, 14., w))
                    .sum()
            }),
            line_width,
            0.,
            25.,
            0.,
        )
        .max(38.)
            + if narrow { 25. } else { 0. };
        self.compare_height
            .duration(if self.compare { compare_size + 12. } else { 0. }, 0.4, cx);
        let compare_height = self.compare_height.get(w, cx).max(0.);
        let output = column()
            .pt(px(if narrow { 16. } else { 20. }))
            .border_t_1()
            .border_color(p.line)
            .child(written)
            .when(compare_height > 0.1, |d| {
                d.child(
                    div()
                        .h(px(compare_height))
                        .pt(px(12.))
                        .overflow_hidden()
                        .child(labelled_line(
                            tr(cx, "Target only", "仅目标模型"),
                            baseline,
                            narrow,
                            output_line(&self.plan, baseline, moment, true, None, colors, cx),
                            p,
                            cx,
                        )),
                )
            });
        let knob_target = if self.compare { 1. } else { 0. };
        self.compare_knob.duration(knob_target, 0.3, cx);
        let knob = self.compare_knob.get(w, cx).clamp(0., 1.);
        let comparison = tr(cx, "Compare without speculation", "对照仅目标模型");
        let switch = activate(
            face(
                "decode-compare",
                comparison,
                44.,
                radius.into(),
                Tone::Clear,
                cx,
            )
            .role(Role::Switch)
            .aria_toggled(self.compare.into())
            .tab_stop(ready)
            .justify_start()
            .gap(px(12.))
            .child(
                div()
                    .relative()
                    .w(px(42.))
                    .h(px(24.))
                    .rounded_full()
                    .flex_none()
                    .bg(p.hover.blend(p.bright.opacity(knob)))
                    .child(
                        div()
                            .absolute()
                            .left(px(3. + 18. * knob))
                            .top(px(3.))
                            .size(px(18.))
                            .rounded_full()
                            .bg(Paint::for_mode(ThemeMode::Light).panel)
                            .shadow_sm(),
                    ),
            )
            .child(text(comparison, 14., 20., p.ink)),
            cx,
            |s, _, cx| {
                if s.status == DecodeStatus::Ready {
                    s.compare_clicked(cx);
                }
            },
        );
        let has_slider = self.tokens.is_some();
        let slider = has_slider.then(|| self.slider(ready, p, cx));
        let controls = div()
            .flex()
            .flex_col()
            .items_start()
            .w_full()
            .min_w_0()
            .gap(px(8.))
            .when_some(slider, |d, slider| d.child(slider.w_full()))
            .child(switch)
            .opacity(if ready { 1. } else { 0.5 });
        let stats = self.stats_row(totals, narrow, p, cx);
        let status_announcement = self.announcement.clone();
        let saved = self.bounds.clone();
        let outer = column()
            .relative()
            .w_full()
            .max_w(px(720.))
            .min_w_0()
            .p(px(pad))
            .gap(px(if narrow { 16. } else { 20. }))
            .rounded(radius)
            .border_1()
            .border_color(p.line)
            .bg(p.panel)
            .text_color(p.ink)
            .child(
                row()
                    .items_start()
                    .justify_between()
                    .gap(px(16.))
                    .child(
                        column()
                            .flex_1()
                            .gap(px(2.))
                            .child(
                                text(title.clone(), 16., 22., p.ink)
                                    .font_weight(FontWeight::MEDIUM),
                            )
                            .child(status_view),
                    )
                    .child(actions),
            )
            .child(
                div()
                    .flex()
                    .w_full()
                    .items_start()
                    .min_w_0()
                    .opacity(if ready { 1. } else { 0.5 })
                    .when(stacked_lanes, |d| d.flex_col().gap(px(12.)))
                    .when(!narrow, |d| d.gap(px(16.)))
                    .child(lane_names)
                    .child(lane_content),
            )
            .child(output)
            .child(
                column()
                    .pt(px(if narrow { 12. } else { 20. }))
                    .border_t_1()
                    .border_color(p.line)
                    .gap(px(16.))
                    .child(stats)
                    .child(controls),
            )
            .when(
                self.status == DecodeStatus::Failed && self.allow_retry,
                |d| {
                    d.child(activate(
                        face(
                            "decode-retry",
                            tr(cx, "Retry", "重试"),
                            32.,
                            radius.into(),
                            Tone::Surface,
                            cx,
                        )
                        .px(px(10.))
                        .child(tr(cx, "Retry", "重试")),
                        cx,
                        |_, _, cx| cx.emit(DecodeRetry),
                    ))
                },
            )
            .when_some(
                active.filter(|a| !reduced && time >= a.swept && columns > 0),
                |d, active| {
                    d.child(token_flight(
                        active,
                        time,
                        self.plan.tokens
                            [active.first_token..active.first_token + active.token_count]
                            .to_vec(),
                        columns,
                        sources,
                        destinations,
                    ))
                },
            )
            .child(
                div()
                    .id("decode-announcement")
                    .role(Role::Status)
                    .aria_label(status_announcement)
                    .absolute()
                    .size(px(1.))
                    .overflow_hidden(),
            )
            .child(
                canvas(
                    move |bounds, w, _| {
                        let old = saved.replace(bounds);
                        let visible = |b: Bounds<Pixels>| {
                            b.bottom() > px(0.) && b.top() < w.viewport_size().height
                        };
                        if old.size != bounds.size || visible(old) != visible(bounds) {
                            w.request_animation_frame();
                        }
                    },
                    |_, _, _, _| (),
                )
                .absolute()
                .inset_0(),
            );
        let outer = if let Some(style) = &self.style {
            style(outer)
        } else {
            outer
        };
        outer
            .id(self.id.clone())
            .role(Role::Group)
            .aria_label(title)
    }
}

#[cfg(test)]
mod tests {
    use super::{DecodeRound, DecodeToken, Plan, default_tokens, simulate};
    use gpui::TestAppContext;

    #[test]
    fn recorded_rounds_preserve_leading_spaces_and_costs() {
        let rounds = vec![
            DecodeRound::new(
                vec!["The".into(), " build".into(), " failed".into()],
                2,
                Some(" passed".into()),
            ),
            DecodeRound::new(vec![], 0, Some(".".into())),
        ];
        let plan = Plan::new(&rounds, 0.64, 0.1);
        assert_eq!(plan.text(4), "The build passed.");
        assert_eq!(plan.words, vec![0..1, 1..2, 2..4]);
        let s = &plan.totals[2];
        assert_eq!((s.passes, s.drafted, s.accepted, s.tokens), (2, 3, 2, 4));
        assert!((s.speedup - 4. / 2.3).abs() < 0.0001);
    }

    #[test]
    fn simulation_rolls_back_after_first_miss_and_preserves_the_final_token() {
        let tokens = vec![
            DecodeToken::new("The").with_ease(1.),
            DecodeToken::new(" build").with_ease(0.).with_miss(" test"),
            DecodeToken::new(" passed").with_ease(1.),
            DecodeToken::new(".").with_ease(1.),
        ];
        let rounds = simulate(&tokens, 4, 12);
        assert_eq!(rounds[0].accepted(), 1);
        assert_eq!(rounds[0].draft[1], " test");
        assert_eq!(rounds[0].target.as_deref(), Some(" build"));
        assert_eq!(rounds[1].target.as_deref(), Some("."));
        assert_eq!(Plan::new(&rounds, 0.64, 0.1).text(4), "The build passed.");
    }

    #[test]
    fn sample_uses_the_reference_totals_and_can_replan() {
        let app = TestAppContext::single();
        app.update(|cx| {
            let tokens = default_tokens(cx);
            let rounds = simulate(&tokens, 4, 12);
            let plan = Plan::new(&rounds, 0.64, 0.1);
            let stats = plan.totals.last().unwrap();
            assert_eq!(
                (stats.passes, stats.drafted, stats.accepted, stats.tokens),
                (6, 24, 16, 22)
            );
            let short = Plan::new(&simulate(&tokens, 2, 12), 0.64, 0.1);
            assert!(short.end() > plan.end());
            assert_eq!(short.text(22), plan.text(22));
        });
    }
}

//! Focus and activation shared by installed action controls.
use crate::foundation::Theme;
use gpui::{
    App, Context, Div, ElementId, Role, SharedString, Stateful, Window, div, prelude::*, px,
};

pub fn surface(
    id: impl Into<ElementId>,
    label: impl Into<SharedString>,
    cx: &App,
) -> Stateful<Div> {
    let label = label.into();
    let c = &Theme::global(cx).tokens.colors;
    let outline = c.focus_outline;
    div()
        .id(id)
        .role(Role::Button)
        .debug_selector(|| label.to_string())
        .aria_label(label)
        .tab_index(0)
        .min_h(px(44.))
        .px_3()
        .flex()
        .items_center()
        .justify_center()
        .rounded(Theme::global(cx).tokens.radius.md)
        .border_1()
        .border_color(c.border)
        .bg(c.surface)
        .text_color(c.foreground)
        .cursor_pointer()
        .hover(|s| s.opacity(0.8))
        .focus_visible(move |s| {
            s.shadow(vec![gpui::BoxShadow {
                color: outline,
                offset: gpui::point(px(0.), px(0.)),
                blur_radius: px(0.),
                spread_radius: px(2.),
                inset: false,
            }])
        })
}

pub fn activate<T: 'static>(
    el: Stateful<Div>,
    cx: &Context<T>,
    f: impl Fn(&mut T, &mut Window, &mut Context<T>) + Clone + 'static,
) -> Stateful<Div> {
    // GPUI turns a completed Enter/Space press into one keyboard ClickEvent.
    // Registering a second key-down action also toggles on key-up in Web hosts.
    el.on_click(cx.listener(move |v, _, w, cx| f(v, w, cx)))
}

pub fn action<T: 'static>(
    id: impl Into<ElementId>,
    label: impl Into<SharedString>,
    cx: &Context<T>,
    f: impl Fn(&mut T, &mut Window, &mut Context<T>) + Clone + 'static,
) -> Stateful<Div> {
    let label = label.into();
    activate(surface(id, label.clone(), cx).child(label), cx, f)
}

/// Secondary action with a text label and a full keyboard/touch target.
pub fn quiet<T: 'static>(
    id: impl Into<ElementId>,
    label: impl Into<SharedString>,
    cx: &Context<T>,
    f: impl Fn(&mut T, &mut Window, &mut Context<T>) + Clone + 'static,
) -> Stateful<Div> {
    let c = Theme::global(cx).tokens.colors.clone();
    action(id, label, cx, f)
        .border_0()
        .bg(gpui::transparent_black())
        .text_size(px(12.))
        .text_color(c.text_secondary)
}

/// Monochrome control marks drawn with the same paths on both renderers.
#[derive(Clone, Copy)]
pub enum Mark {
    Hold,
    Check,
    Mic,
    Stop,
    Chevron,
    Up,
    Spark,
    Heart,
}
pub fn mark(kind: Mark, ink: gpui::Hsla) -> impl IntoElement {
    use gpui::{PathBuilder, canvas, point};
    canvas(
        |_, _, _| (),
        move |b, _, w, _| {
            let at = |x: f32, y: f32| point(b.origin.x + px(x), b.origin.y + px(y));
            let mut p = PathBuilder::stroke(px(1.55));
            match kind {
                Mark::Hold => {
                    p.move_to(at(3., 10.));
                    p.curve_to(at(8., 2.5), at(2.4, 2.7));
                    p.curve_to(at(13.3, 8.), at(13.2, 2.5));
                    p.move_to(at(4.6, 13.));
                    p.curve_to(at(5.5, 7.5), at(6., 10.5));
                    p.curve_to(at(10.5, 7.5), at(8., 3.5));
                    p.curve_to(at(9.4, 14.), at(11.1, 10.5));
                    p.move_to(at(8., 7.5));
                    p.curve_to(at(7.2, 12.1), at(8.6, 9.2));
                }
                Mark::Check => {
                    p.move_to(at(2.3, 8.1));
                    p.line_to(at(6.5, 12.));
                    p.line_to(at(13.8, 3.6));
                }
                Mark::Mic => {
                    p.move_to(at(5.4, 4.));
                    p.curve_to(at(10.6, 4.), at(8., -0.9));
                    p.line_to(at(10.6, 7.8));
                    p.curve_to(at(5.4, 7.8), at(8., 12.5));
                    p.line_to(at(5.4, 4.));
                    p.move_to(at(2.5, 7.5));
                    p.curve_to(at(13.5, 7.5), at(8., 16.5));
                    p.move_to(at(8., 12.));
                    p.line_to(at(8., 15.));
                    p.move_to(at(5.5, 15.));
                    p.line_to(at(10.5, 15.));
                }
                Mark::Stop => {
                    p = PathBuilder::fill();
                    p.move_to(at(3.5, 3.5));
                    p.line_to(at(12.5, 3.5));
                    p.line_to(at(12.5, 12.5));
                    p.line_to(at(3.5, 12.5));
                    p.close();
                }
                Mark::Up => {
                    p.move_to(at(8., 13.5));
                    p.line_to(at(8., 2.5));
                    p.move_to(at(3.2, 7.5));
                    p.line_to(at(8., 2.5));
                    p.line_to(at(12.8, 7.5));
                }
                Mark::Spark => {
                    p.move_to(at(8., 1.5));
                    p.curve_to(at(14.5, 8.), at(9.2, 6.7));
                    p.curve_to(at(8., 14.5), at(9.2, 9.3));
                    p.curve_to(at(1.5, 8.), at(6.8, 9.3));
                    p.curve_to(at(8., 1.5), at(6.8, 6.7));
                    p.close();
                }
                Mark::Heart => {
                    p.move_to(at(8., 13.8));
                    p.cubic_bezier_to(at(1.8, 5.6), at(5., 11.5), at(1.8, 8.6));
                    p.cubic_bezier_to(at(8., 4.4), at(1.8, 2.), at(5.8, 1.6));
                    p.cubic_bezier_to(at(14.2, 5.6), at(10.2, 1.6), at(14.2, 2.));
                    p.cubic_bezier_to(at(8., 13.8), at(14.2, 8.6), at(11., 11.5));
                    p.close();
                }
                Mark::Chevron => {
                    p.move_to(at(5., 6.5));
                    p.line_to(at(8., 9.5));
                    p.line_to(at(11., 6.5));
                }
            }
            if let Ok(path) = p.build() {
                w.paint_path(path, ink);
            }
        },
    )
    .size(px(16.))
    .flex_none()
}

/// Optional host language for labels owned by action controls; English is the default.
#[derive(Clone, Copy, Default, PartialEq, Eq)]
pub enum UiLanguage {
    #[default]
    English,
    Chinese,
}
impl gpui::Global for UiLanguage {}
impl UiLanguage {
    pub fn current(cx: &App) -> Self {
        cx.try_global::<Self>().copied().unwrap_or_default()
    }
    pub fn text<'a>(self, english: &'a str, chinese: &'a str) -> &'a str {
        match self {
            Self::English => english,
            Self::Chinese => chinese,
        }
    }
}

/// Optional host writing direction; left-to-right is the default. GPUI has no
/// direction property, so controls that place things on an inline axis read
/// this the way the Web reads `getComputedStyle(...).direction`.
#[derive(Clone, Copy, Default, PartialEq, Eq)]
pub enum UiDirection {
    #[default]
    Ltr,
    Rtl,
}
impl gpui::Global for UiDirection {}
impl UiDirection {
    pub fn current(cx: &App) -> Self {
        cx.try_global::<Self>().copied().unwrap_or_default()
    }
    pub fn is_rtl(self) -> bool {
        matches!(self, Self::Rtl)
    }
    /// Reverse the inline step when the reading direction runs the other way.
    pub fn inline_step(self, step: isize) -> isize {
        if self.is_rtl() { -step } else { step }
    }
}

//! Compact action surfaces scoped to the button family.
use crate::foundation::{AccentPalette, Theme, ThemeMode};
use gpui::{prelude::*, *};
use web_time::Instant;
#[derive(Debug, Clone, Copy, Default, PartialEq, Eq)]
pub enum Tone {
    #[default]
    Surface,
    Primary,
    Muted,
    Danger,
    Success,
    Clear,
}
#[derive(Clone, Copy)]
pub struct Paint {
    pub stage: Hsla,
    pub panel: Hsla,
    pub tray: Hsla,
    pub hover: Hsla,
    pub ink: Hsla,
    pub secondary: Hsla,
    pub faint: Hsla,
    pub line: Hsla,
    pub bright: Hsla,
    pub(crate) focus: Hsla,
    pub inverse: Hsla,
    pub(crate) neutral_inverse: Hsla,
    accent: AccentPalette,
    pub danger: Hsla,
    pub success: Hsla,
}
impl Paint {
    pub fn get(cx: &App) -> Self {
        Self::for_theme(Theme::global(cx))
    }
    pub(crate) fn for_theme(theme: &Theme) -> Self {
        let mut paint = Self::for_mode(theme.mode);
        let tint = theme.accent.for_mode(theme.mode);
        if tint.is_transparent() {
            return paint;
        }
        paint.accent = theme.accent;
        paint.bright = paint.bright.blend(tint);
        paint.focus = theme.tokens.colors.focus_outline;
        paint.inverse = paint.accent.on_fill(paint.bright, paint.neutral_inverse);
        paint.hover = paint.hover.blend(tint.opacity(0.12));
        paint
    }
    pub(crate) fn primary_hover(self, strength: f32) -> Hsla {
        self.bright.blend(
            self.accent
                .hover_tint(self.bright, self.inverse, strength)
                .opacity(strength),
        )
    }
    pub fn for_mode(mode: ThemeMode) -> Self {
        let dark = mode == ThemeMode::Dark;
        let [
            stage,
            panel,
            tray,
            hover,
            ink,
            secondary,
            faint,
            line,
            bright,
            inverse,
            danger,
        ] = if dark {
            [
                0x242424, 0x191919, 0x303030, 0x353535, 0xf2f2f2, 0xb5b5b5, 0x898989, 0x2b2b2b,
                0xf2f2f2, 0x141414, 0xff746f,
            ]
        } else {
            [
                0xf5f5f5, 0xffffff, 0xffffff, 0xe9e9e9, 0x1a1a1a, 0x575757, 0x747474, 0xe2e2e2,
                0x181818, 0xfafafa, 0xbd302c,
            ]
        };
        Self {
            stage: rgb(stage).into(),
            panel: rgb(panel).into(),
            tray: rgb(tray).into(),
            hover: rgb(hover).into(),
            ink: rgb(ink).into(),
            secondary: rgb(secondary).into(),
            faint: rgb(faint).into(),
            line: rgb(line).into(),
            bright: rgb(bright).into(),
            focus: rgb(bright).into(),
            inverse: rgb(inverse).into(),
            neutral_inverse: rgb(inverse).into(),
            accent: AccentPalette::default(),
            danger: rgb(danger).into(),
            success: rgb(if dark { 0x53d986 } else { 0x008039 }).into(),
        }
    }
    pub fn colors(self, t: Tone) -> (Hsla, Hsla) {
        match t {
            Tone::Primary => (self.bright, self.inverse),
            Tone::Success => (self.panel.blend(self.success.opacity(0.10)), self.ink),
            Tone::Muted => (self.secondary, self.neutral_inverse),
            Tone::Clear => (transparent_black(), self.ink),
            _ => (self.panel, self.ink),
        }
    }
}
pub fn face(
    id: impl Into<ElementId>,
    name: impl Into<SharedString>,
    height: f32,
    r: f32,
    t: Tone,
    cx: &App,
) -> Stateful<Div> {
    let p = Paint::get(cx);
    let (bg, fg) = p.colors(t);
    let name = name.into();
    let ring = Theme::global(cx).tokens.colors.focus_outline;
    div()
        .id(id)
        .debug_selector({
            let name = name.clone();
            move || name.to_string()
        })
        .aria_label(name)
        .role(Role::Button)
        .tab_index(0)
        .h(px(height))
        .flex_none()
        .flex()
        .items_center()
        .justify_center()
        .gap(px(8.))
        .rounded(px(r))
        .bg(bg)
        .text_color(fg)
        .text_size(px(14.))
        .line_height(px(19.6))
        .font_weight(FontWeight::MEDIUM)
        .whitespace_nowrap()
        .cursor_pointer()
        .when(t == Tone::Danger, |e| {
            e.border_1().border_color(p.danger.opacity(0.42))
        })
        .when(t == Tone::Success, |e| {
            e.border_1().border_color(p.success.opacity(0.40))
        })
        .focus_visible(move |s| s.border_1().border_color(ring))
}
/// Analytic critically damped spring. Retargeting preserves instantaneous velocity.
#[derive(Clone, Copy, Debug)]
pub struct Slide {
    from: f32,
    to: f32,
    velocity: f32,
    start: Option<Instant>,
    omega: f32,
}
impl Slide {
    pub fn new(v: f32) -> Self {
        Self {
            from: v,
            to: v,
            velocity: 0.,
            start: None,
            omega: 12.47,
        }
    }
    pub fn snappy(v: f32) -> Self {
        Self {
            omega: 20.14,
            ..Self::new(v)
        }
    }
    /// Re-express the same trajectory in a shifted coordinate system, preserving velocity.
    pub fn translate(&mut self, delta: f32) {
        self.from += delta;
        self.to += delta;
    }
    pub fn reset(&mut self, v: f32) {
        self.from = v;
        self.to = v;
        self.velocity = 0.;
        self.start = None;
    }
    pub fn set(&mut self, v: f32, cx: &App) {
        self.retarget(v, self.omega, cx);
    }
    pub fn duration(&mut self, v: f32, visual_seconds: f32, cx: &App) {
        self.retarget(v, 5.236 / visual_seconds, cx)
    }
    /// Settle a directly manipulated value with the measured release speed (units per second).
    pub(crate) fn release(&mut self, target: f32, velocity: f32, seconds: f32, cx: &App) {
        if disabled_motion(cx) {
            self.reset(target);
            return;
        }
        let now = cx.background_executor().now();
        self.from = self.sample(now).0;
        self.to = target;
        self.velocity = velocity;
        self.omega = 5.236 / seconds;
        self.start = Some(now);
    }
    /// Stagger a first reveal without advancing the value before its slot starts.
    pub(crate) fn delayed(&mut self, target: f32, seconds: f32, delay: f32, cx: &App) {
        if self.to == target {
            return;
        }
        self.duration(target, seconds, cx);
        if let Some(start) = self.start.as_mut() {
            *start += std::time::Duration::from_secs_f32(delay.max(0.));
        }
    }
    fn retarget(&mut self, v: f32, omega: f32, cx: &App) {
        if disabled_motion(cx) {
            self.reset(v);
            return;
        }
        if self.to == v {
            return;
        }
        let now = cx.background_executor().now();
        let (pos, vel, _) = self.sample(now);
        self.from = pos;
        self.velocity = vel;
        self.omega = omega;
        self.to = v;
        self.start = Some(now);
    }
    pub(crate) fn sample(&self, now: Instant) -> (f32, f32, bool) {
        let Some(start) = self.start else {
            return (self.to, 0., false);
        };
        let t = now.saturating_duration_since(start).as_secs_f32();
        let d = self.from - self.to;
        let k = self.velocity + self.omega * d;
        let e = (-self.omega * t).exp();
        let offset = (d + k * t) * e;
        let vel = (self.velocity - self.omega * k * t) * e;
        if offset.abs() < 0.0008 && vel.abs() < 0.012 || t > 1.6 {
            (self.to, 0., false)
        } else {
            (self.to + offset, vel, true)
        }
    }
    /// Sample several springs at one instant and let the caller schedule a single frame.
    pub(crate) fn sample_batch(&self, now: Instant, reduced: bool) -> (f32, bool) {
        if reduced {
            (self.to, false)
        } else {
            let (value, _, active) = self.sample(now);
            (value, active)
        }
    }
    /// Sample from an input handler without scheduling a frame outside paint.
    pub fn value(&self, cx: &App) -> f32 {
        if disabled_motion(cx) {
            self.to
        } else {
            self.sample(cx.background_executor().now()).0
        }
    }
    pub fn get(&self, w: &Window, cx: &App) -> f32 {
        if disabled_motion(cx) {
            return self.to;
        }
        let (v, _, m) = self.sample(cx.background_executor().now());
        if m {
            w.request_animation_frame()
        }
        v
    }
}
pub fn disabled_motion(cx: &App) -> bool {
    cx.try_global::<Theme>().is_some_and(|t| t.reduced_motion)
}
/// A finite paint clock; never schedules frames once its last phase has finished.
#[derive(Clone, Copy, Default, Debug)]
pub struct PhaseClock(Option<Instant>);
impl PhaseClock {
    pub fn restart(&mut self, cx: &App) {
        self.0 = Some(cx.background_executor().now())
    }
    pub fn age(self, cx: &App) -> f32 {
        self.0.map_or(f32::INFINITY, |s| {
            cx.background_executor()
                .now()
                .saturating_duration_since(s)
                .as_secs_f32()
        })
    }
    pub fn time(self, end: f32, w: &Window, cx: &App) -> f32 {
        if disabled_motion(cx) {
            return end;
        }
        let t = self.age(cx);
        if t < end {
            w.request_animation_frame()
        }
        t.min(end)
    }
}
pub fn ease(t: f32) -> f32 {
    cubic_out(t, 0.16, 0.30)
}
/// Cubic-bezier(.22, 1, .36, 1) used by page-scale wipes.
pub fn standard_ease(x: f32) -> f32 {
    cubic_out(x, 0.22, 0.36)
}
fn cubic_out(x: f32, x1: f32, x2: f32) -> f32 {
    if x <= 0. || x >= 1. {
        return x.clamp(0., 1.);
    }
    let (mut lo, mut hi) = (0., 1.);
    for _ in 0..14 {
        let t = (lo + hi) * 0.5;
        let v = 1. - t;
        let at = 3. * x1 * v * v * t + 3. * x2 * v * t * t + t * t * t;
        if at < x { lo = t } else { hi = t }
    }
    1. - (1. - (lo + hi) * 0.5_f32).powi(3)
}
pub fn measure(text: &SharedString, size: f32, w: &Window) -> f32 {
    let mut style = w.text_style();
    style.font_weight = FontWeight::MEDIUM;
    let advance: f32 = w
        .text_system()
        .shape_line(text.clone(), px(size), &[style.to_run(text.len())], None)
        .width
        .into();
    (advance - 0.01 * size * text.chars().count() as f32).max(0.)
}
/// Pointer feedback lives in the element's stable hit box, independent of its paint.
pub fn press<T: 'static>(
    el: Stateful<Div>,
    cx: &Context<T>,
    field: fn(&mut T) -> &mut Slide,
) -> Stateful<Div> {
    el.on_mouse_down(
        MouseButton::Left,
        cx.listener(move |v, _, _, cx| {
            field(v).set(1., cx);
            cx.notify()
        }),
    )
    .on_mouse_up(
        MouseButton::Left,
        cx.listener(move |v, _, _, cx| {
            field(v).set(0., cx);
            cx.notify()
        }),
    )
    .on_mouse_up_out(
        MouseButton::Left,
        cx.listener(move |v, _, _, cx| {
            field(v).set(0., cx);
            cx.notify()
        }),
    )
    .on_key_down(cx.listener(move |v, e: &KeyDownEvent, _, cx| {
        if matches!(e.keystroke.key.as_str(), "enter" | "space") {
            field(v).set(1., cx);
            cx.notify()
        }
    }))
    .on_key_up(cx.listener(move |v, e: &KeyUpEvent, _, cx| {
        if matches!(e.keystroke.key.as_str(), "enter" | "space") {
            field(v).set(0., cx);
            cx.notify()
        }
    }))
}

/// Stable glyph identities are matched in reading order, including common suffixes.
fn shared_glyphs(
    left: &[(SharedString, f32)],
    right: &[(SharedString, f32)],
) -> Vec<Option<usize>> {
    let stride = right.len() + 1;
    let mut lcs = vec![0u16; (left.len() + 1) * stride];
    for i in (0..left.len()).rev() {
        for j in (0..right.len()).rev() {
            lcs[i * stride + j] = if left[i].0 == right[j].0 {
                1 + lcs[(i + 1) * stride + j + 1]
            } else {
                lcs[(i + 1) * stride + j].max(lcs[i * stride + j + 1])
            };
        }
    }
    let mut out = vec![None; left.len()];
    let (mut i, mut j) = (0, 0);
    while i < left.len() && j < right.len() {
        if left[i].0 == right[j].0 {
            out[i] = Some(j);
            i += 1;
            j += 1
        } else if lcs[(i + 1) * stride + j] >= lcs[i * stride + j + 1] {
            i += 1
        } else {
            j += 1
        }
    }
    out
}
/// Paint two label phases in one measured slot; the outgoing face never affects layout.
pub fn lettering(
    old: SharedString,
    new: SharedString,
    time: f32,
    letters: bool,
    size: f32,
    ink: Hsla,
    width: f32,
) -> impl IntoElement {
    canvas(
        |_, _, _| (),
        move |b, _, w, cx| {
            let plain = old == new || time >= 0.48;
            let mut style = w.text_style();
            style.font_weight = FontWeight::MEDIUM;
            let width_of = |s: &SharedString| {
                f32::from(
                    w.text_system()
                        .shape_line(s.clone(), px(size), &[style.to_run(s.len())], None)
                        .width,
                )
            };
            let old_x = (width - width_of(&old)) * 0.5;
            let new_x = (width - width_of(&new)) * 0.5;
            if plain {
                let mut run = style.to_run(new.len());
                run.color = ink;
                let line = w
                    .text_system()
                    .shape_line(new.clone(), px(size), &[run], None);
                let _ = line.paint(
                    b.origin + point(px(new_x), px(0.)),
                    b.size.height,
                    TextAlign::Left,
                    None,
                    w,
                    cx,
                );
                return;
            }
            let pieces = |s: &SharedString| -> Vec<(SharedString, f32)> {
                let line =
                    w.text_system()
                        .shape_line(s.clone(), px(size), &[style.to_run(s.len())], None);
                s.char_indices()
                    .map(|(i, c)| (c.to_string().into(), line.x_for_index(i).into()))
                    .collect()
            };
            let mut runs = Vec::new();
            if letters && old.len() < 256 && new.len() < 256 {
                let left = pieces(&old);
                let right = pieces(&new);
                let pairs = shared_glyphs(&left, &right);
                let mut stable = vec![false; right.len()];
                let out = 1. - standard_ease(time / 0.16);
                let layout = 1. - (1. + 12.47 * time) * (-12.47 * time).exp();
                for ((glyph, dx), matched) in left.into_iter().zip(pairs) {
                    if let Some(j) = matched {
                        let x = old_x + dx;
                        stable[j] = true;
                        runs.push((glyph, x + (new_x + right[j].1 - x) * layout, 0., 1., 0.));
                    } else {
                        runs.push((glyph, old_x + dx, -3. * (1. - out), out, 2. * (1. - out)));
                    }
                }
                let mut order = 0;
                for ((glyph, dx), matched) in right.into_iter().zip(stable) {
                    if !matched {
                        let k = ease((time - (order as f32 * 0.016).min(0.1)) / 0.24);
                        runs.push((glyph, new_x + dx, 4. * (1. - k), k, 2. * (1. - k)));
                        order += 1;
                    }
                }
            } else {
                let incoming = ease(time / 0.16);
                runs.push((old.clone(), old_x, 0., 1. - standard_ease(time / 0.10), 0.));
                runs.push((new.clone(), new_x, 2. * (1. - incoming), incoming, 0.));
            }
            for (s, x, y, alpha, blur) in runs {
                if alpha < 0.001 || s.is_empty() {
                    continue;
                }
                let taps = if blur > 0.22 { 5 } else { 1 };
                let mut run = style.to_run(s.len());
                run.color = ink.opacity(alpha / if taps == 5 { 4.3 } else { 1. });
                let line = w.text_system().shape_line(s, px(size), &[run], None);
                for (dx, dy) in [(0., 0.), (-0.7, 0.), (0.7, 0.), (0., -0.7), (0., 0.7)]
                    .into_iter()
                    .take(taps)
                {
                    let _ = line.paint(
                        b.origin + point(px(x + dx * blur), px(y + dy * blur)),
                        b.size.height,
                        TextAlign::Left,
                        None,
                        w,
                        cx,
                    );
                }
            }
        },
    )
    .w(px(width.max(0.)))
    .h(px(size * 1.4))
    .flex_none()
}

#[cfg(test)]
mod spring_tests {
    use super::{Instant, Slide};
    use std::time::Duration;
    #[test]
    fn reversing_keeps_position_and_velocity() {
        let s = Instant::now();
        let mid = s + Duration::from_millis(75);
        let a = Slide {
            start: Some(s),
            to: 1.,
            ..Slide::new(0.)
        };
        let (x, v, _) = a.sample(mid);
        let reversed = Slide {
            start: Some(mid),
            from: x,
            velocity: v,
            to: 0.,
            ..a
        };
        assert_eq!(reversed.sample(mid), (x, v, true));
        assert_eq!(reversed.sample_batch(mid, false), (x, true));
        assert_eq!(reversed.sample_batch(mid, true), (0., false));
        assert!(reversed.sample(mid + Duration::from_millis(240)).0 < x);
        assert_eq!(
            reversed.sample(mid + Duration::from_secs(2)),
            (0., 0., false)
        );
    }
    #[test]
    fn unchanged_suffix_keeps_its_identity_across_label_swaps() {
        let glyphs = |s: &str| {
            s.chars()
                .map(|g| (gpui::SharedString::from(g.to_string()), 0.))
                .collect::<Vec<_>>()
        };
        let old = glyphs("Add to library");
        let new = glyphs("In library");
        let pairs = super::shared_glyphs(&old, &new);
        assert_eq!(
            &pairs[old.len() - 7..],
            &[
                Some(3),
                Some(4),
                Some(5),
                Some(6),
                Some(7),
                Some(8),
                Some(9)
            ]
        );
        assert_eq!(
            super::shared_glyphs(&glyphs("添加成员"), &glyphs("移除成员")),
            vec![None, None, Some(2), Some(3)]
        );
    }
}

#[cfg(test)]
mod accent_tests {
    use super::{AccentPalette, Paint, Theme, ThemeMode};
    use gpui::{Hsla, rgb};
    #[test]
    fn custom_accent_preserves_fill_and_picks_readable_ink_in_both_modes() {
        // Color pairs include near-threshold grays and hues with high/low relative
        // luminance despite identical HSL lightness (yellow and blue).
        for (hex, expected) in [
            (0xffffff, Hsla::black()),
            (0x000000, Hsla::white()),
            (0xffff00, Hsla::black()),
            (0x0000ff, Hsla::white()),
            (0x757575, Hsla::white()),
            (0x767676, Hsla::black()),
            (0xdfa4ef, Hsla::black()),
            (0x221144, Hsla::white()),
        ] {
            let fill: Hsla = rgb(hex).into();
            let accent = AccentPalette {
                light: fill,
                dark: fill,
            };
            let mut theme = Theme::default();
            theme.set_accent(accent);
            for mode in [ThemeMode::Light, ThemeMode::Dark] {
                theme.set_mode(mode);
                let colors = &theme.tokens.colors;
                let p = Paint::for_theme(&theme);
                assert_eq!(colors.accent, fill);
                assert_eq!(p.bright, fill);
                assert_eq!(colors.accent_foreground, expected, "#{hex:06x}");
                assert_eq!(p.inverse, expected);
                assert!(AccentPalette::contrast(p.inverse, p.bright) >= 4.5);
                assert!(AccentPalette::contrast(p.inverse, p.primary_hover(0.12)) >= 4.5);
                assert!(AccentPalette::contrast(colors.focus_outline, colors.surface_muted) >= 3.5);
                assert!(AccentPalette::contrast(colors.focus_outline, p.stage) >= 3.);
                // A tint applies to the primary fill, never to text on neutral/status surfaces.
                assert_eq!(p.neutral_inverse, Paint::for_mode(mode).inverse);
            }
        }
    }

    #[test]
    fn theme_presets_keep_their_authored_inks_and_focus_colors() {
        for (light, dark) in [
            (0x245bc4, 0x8bb4ff),
            (0x7142b6, 0xbc9cff),
            (0x08776d, 0x68d4c4),
            (0xb93c67, 0xff94b3),
            (0x955a08, 0xf4be69),
        ] {
            let mut theme = Theme::default();
            let pair = AccentPalette {
                light: rgb(light).into(),
                dark: rgb(dark).into(),
            };
            theme.set_accent(pair);
            for mode in [ThemeMode::Light, ThemeMode::Dark] {
                theme.set_mode(mode);
                let p = Paint::for_theme(&theme);
                let neutral = Paint::for_mode(mode);
                assert_eq!(p.bright, pair.for_mode(mode));
                assert_eq!(p.inverse, neutral.inverse);
                assert_eq!(theme.tokens.colors.focus_outline, pair.for_mode(mode));
            }
            theme.set_accent(AccentPalette::default());
            let p = Paint::for_theme(&theme);
            let neutral = Paint::for_mode(theme.mode);
            assert_eq!(p.bright, neutral.bright);
            assert_eq!(p.inverse, neutral.inverse);
        }
    }
}

